using MessagePack;
using MessagePack.Formatters;
using ProjectA;

// old: GeneratedMessagePackFormatterAttribute does not exist (CS0246), no MsgPack021.
// new: MsgPack021 on MyTypeFormatter, because the formatted type ProjectA.MyType is abstract.
[GeneratedMessagePackFormatter]
public partial class MyTypeFormatter : IMessagePackFormatter<MyType>
{
    // Hand-written members so the only new-side diagnostic is MsgPack021 (nothing is generated when it fires).
    public void Serialize(ref MessagePackWriter writer, MyType value, MessagePackSerializerOptions options) => throw new System.NotImplementedException();

    public MyType Deserialize(ref MessagePackReader reader, MessagePackSerializerOptions options) => throw new System.NotImplementedException();
}
